CustomField.formula:
IF(Current_Year_Red_Revenue__c < 1000, TEXT(FLOOR(Current_Year_Red_Revenue__c)),
  IF(Current_Year_Red_Revenue__c < 1000000, TEXT(FLOOR(Current_Year_Red_Revenue__c/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Red_Revenue__c)), 3),
    IF(Current_Year_Red_Revenue__c < 1000000000, TEXT(FLOOR(Current_Year_Red_Revenue__c/1000000)) & ',' & TEXT(FLOOR(MOD(Current_Year_Red_Revenue__c,1000000)/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Red_Revenue__c)), 3), "Error:Number Greater Than 999,999,999")
  )
)
